using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.Mvc;

using Fanex.Security.SpamFilter;
using Fanex.Security.SpamFilter.Entity;
using System.Threading;

namespace Fanex.Security.SpamFilter.Test.Controllers
{
    public class HomeController : Controller
    {
        public ActionResult Index()
        {
            ViewBag.Message = "Modify this template to jump-start your ASP.NET MVC application.";

            return View();
        }

        public ActionResult About()
        {
            ViewBag.Message = "Your quintessential app description page.";

            return View();
        }

        public ActionResult Contact()
        {
            if (Request["reset"] == "true")
            {
                // Oh, clear rule 10
                System.Web.HttpContext.Current.SpamFilterResetRule("Home.Captcha");
            }

            ICollection<IRequestBlocker> blockers = System.Web.HttpContext.Current.GetSpamFilterBlockers();

            if (blockers.Count == 0)
            {
                if (Request["violated"] == "true")
                {
                    Thread.Sleep(500);

                    // Oh, it violates our rule
                    System.Web.HttpContext.Current.SpamFilterIncrement();
                }
            }

            ViewBag.Message = "Your quintessential contact page. ";
            return View();
        }
    }
}